import operator
import random

OPERATIONS = {
    "+": operator.add,
    "-": operator.sub,
    "*": operator.mul,
}


def make_question():
    symbol = random.choice(list(OPERATIONS))
    if symbol == "*":
        a, b = random.randint(1, 12), random.randint(1, 12)
    else:
        a, b = random.randint(1, 50), random.randint(1, 50)
        if symbol == "-" and b > a:
            a, b = b, a
    return f"{a} {symbol} {b}", OPERATIONS[symbol](a, b)


def ask(question):
    while True:
        reply = input(f"What is {question}? ").strip()
        if reply.lower() in ("q", "quit"):
            return None
        try:
            return int(reply)
        except ValueError:
            print("Please enter a whole number (or 'q' to quit).")


def main():
    print("Arithmetic game! Type 'q' to quit at any time.\n")
    score = rounds = 0
    while True:
        question, answer = make_question()
        guess = ask(question)
        if guess is None:
            break
        rounds += 1
        if guess == answer:
            score += 1
            print(f"Correct! Score: {score}/{rounds}\n")
        else:
            print(f"Not quite, {question} = {answer}. Score: {score}/{rounds}\n")
    print(f"Thanks for playing! Final score: {score}/{rounds}")


if __name__ == "__main__":
    main()
